        scwin.chng_stk_rel_corpbnd_rght_tp_cd('' + dma_pageContext.get("stk_rel_corpbnd_rght_tp_cd") + '');
        $("input[name='stkRelCorpbndExerPrc']").trigger('onkeyup');
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf10101.onpageload' }); }
};

// [A] 초기 목록 미해결 — jldinf10101: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_conds();
        scwin.init_datefmt_cal_exerStrtDd();
        scwin.init_datefmt_cal_exerEndDd();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldinf10101.onpageload' });
    }
};


