            chk_cash_pay_yn = "Y";
        }
        if ((String($c.util.getComponent('chk_sb_pay_yn').getValue() || "") !== "")) {
            chk_sb_pay_yn = "Y";
        }
        if (($c.util.getComponent('ipt_clmInstCd').getValue() == null ? '' : String($c.util.getComponent('ipt_clmInstCd').getValue())) === '') {

        }
    }
