        await $c.win.alert("누적여부를 선택하세요.");
        scwin.proft_partc_acc_yn.focus();
        return;
    }
    (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).getComponentById("slc_stkRelCorpbndRghtTpCd")) || { setValue: function () {} }).setValue($c.util.getComponent('slc_stkRelCorpbndRghtTpCd').getValue());
    (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).getComponentById("ipt_objIsuCd")) || { setValue: function () {} }).setValue($c.util.getComponent('ipt_objIsuCd').getValue());
